import boto3

def check_text_safety(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(
        Text=text,
        LanguageCode='en'
    )
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return 'Unsafe'
    else:
        return 'Safe'

from boto3.dynamodb.conditions import Key, Attr


def create_item(table, item):
    response = table.put_item(Item=item)
    return response


def get_item(table, key):
    response = table.get_item(Key=key)
    return response.get('Item')


def query_items(table, key_condition_expression):
    response = table.query(KeyConditionExpression=key_condition_expression)
    return response.get('Items')


def normalize_item(item):
    normalized_item = {}
    for key, value in item.items():
        if isinstance(value, dict):
            normalized_item[key] = normalize_item(value)
        else:
            normalized_item[key] = value
    return normalized_item

import os
import boto3

# Configure AWS credentials from environment variables
aws_access_key_id = os.getenv('AWS_ACCESS_KEY_ID')
aws_secret_access_key = os.getenv('AWS_SECRET_ACCESS_KEY')
aws_region = os.getenv('AWS_REGION', 'us-west-2')

# Create a DynamoDB client
dynamodb_client = boto3.client(
    'dynamodb',
    region_name=aws_region,
    aws_access_key_id=aws_access_key_id,
    aws_secret_access_key=aws_secret_access_key
)

def create_table(table_name, key_schema, attribute_definitions, provisioned_throughput):
    return dynamodb_client.create_table(
        TableName=table_name,
        KeySchema=key_schema,
        AttributeDefinitions=attribute_definitions,
        ProvisionedThroughput=provisioned_throughput
    )

def get_item(table_name, key):
    return dynamodb_client.get_item(
        TableName=table_name,
        Key=key
    )

def put_item(table_name, item):
    return dynamodb_client.put_item(
        TableName=table_name,
        Item=item
    )

import boto3

def fetch_document(table_name, document_id):
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table(table_name)
    response = table.get_item(
        Key={'id': document_id}
    )
    return response.get('Item', None)

if __name__ == '__main__':
    table_name = 'Documents'
    document_id = 'example-id'
    document = fetch_document(table_name, document_id)
    if document:
        print(f'Document found: {document}')
    else:
        print('Document not found')

import boto3

def upsert_document(table_name, primary_key, document):
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table(table_name)
    response = table.put_item(
        Item={
            primary_key: document[primary_key],
            'document': document
        }
    )
    return response
